'use strict';
document.addEventListener('toggle',e=>{const id=e.target.dataset?.tactics;if(!id||!e.target.isConnected)return;UI.quickTactics=(UI.quickTactics||[]).filter(x=>x!==id);if(e.target.open)UI.quickTactics.push(id)},true);
const flowRender=render;render=function(){const focused=document.activeElement;flowRender();if(focused?.tagName==='SELECT'&&focused.dataset.chg!=='keeperStep'){const replacement=[...document.querySelectorAll('select')].find(el=>focused.id?el.id===focused.id:JSON.stringify(el.dataset)===JSON.stringify(focused.dataset));replacement?.focus({preventScroll:true})}};

function clubBeasts(){return G.clubs.P.roster.map(id=>G.beasts[id]).filter(Boolean)}
function canManageClub(){return !!G&&['hub','prematch'].includes(UI.mode)}
function armoryBeast(){return clubBeasts().find(b=>b.id===UI.armoryBeast)||clubBeasts().find(b=>ROLE_LINE[roleOf(b)]==='front')||clubBeasts()[0]}
function gearIcon(slot){return {claw:'✦',armor:'⬡',charm:'◇'}[slot]}
function gearFit(slot){return {claw:'Attack pieces help damage dealers.',armor:'Barding helps your front line survive.',charm:'Charms tune a beast’s specialty.'}[slot]}
function gearSummary(b){return Object.keys(SLOTS).map(slot=>{const item=b.gear?.[slot];return `<div class="loadout-slot"><span aria-hidden="true">${gearIcon(slot)}</span><div><small>${SLOTS[slot]}</small><b>${item?esc(ITEMS[item.key].n):'Empty slot'}</b></div></div>`}).join('')}

viewShop=function(){
 const b=armoryBeast(),slot=UI.armorySlot||'armor',mine=clubBeasts(),purchase=G.stash.find(x=>x.id===UI.armoryPurchase);
 const owned=k=>G.stash.filter(x=>x.key===k).length+mine.reduce((n,x)=>n+Object.values(x.gear||{}).filter(g=>g?.key===k).length,0);
 const stash=G.stash.filter(x=>ITEMS[x.key].slot===slot);
 return `<div class="armory-page stack"><div class="section-heading"><div><span class="lbl gold">Fit for the arena</span><h2 style="margin-top:8px">The Armory</h2><p class="note">Choose a beast, buy a piece, then equip it. Buying keeps an item in your shared stash until you attach it.</p></div><span class="chip">Gold <b>${fmt(G.gold)}</b></span></div>
 <section class="panel armory-recipient" data-guide="armory-recipient">${beastArt(b.sp)}<div><label class="lbl" for="armory-beast">Outfit a beast</label><select id="armory-beast" data-chg="armoryBeast">${mine.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)} · ${SPECIES[x.sp].n} · ${roleOf(x)}</option>`).join('')}</select><p class="note">One item in each slot. Replacing a piece returns the old one to your stash.</p></div><button class="btn sm" data-act="profile" data-id="${b.id}" data-pt="gear">View gear & supplies</button><div class="loadout-summary">${gearSummary(b)}</div></section>
 ${purchase?`<section class="purchase-receipt" data-guide="purchase"><div><span class="lbl gold">Purchased · waiting in your stash</span><h3>${esc(ITEMS[purchase.key].n)}</h3><p>${esc(modText(ITEMS[purchase.key].m))}</p></div><button class="btn pri" data-act="equip" data-id="${b.id}" data-item="${purchase.id}">Equip on ${esc(b.name)}</button></section>`:''}
 <div class="armory-layout"><div class="stack"><section class="panel" data-guide="catalog"><div class="row between"><h3>Choose your equipment</h3><span class="note">${TIERS[G.tier].n} stock</span></div><div class="seg armory-filters" role="group" aria-label="Equipment slot">${Object.entries(SLOTS).map(([k,n])=>`<button data-act="armorySlot" data-k="${k}" class="${slot===k?'on':''}" aria-pressed="${slot===k}">${gearIcon(k)} ${n}</button>`).join('')}</div><p class="note">${gearFit(slot)} Keep ${playerUpkeep()} gold available for your next matchday’s upkeep.</p><div class="icards">${Object.entries(ITEMS).filter(([k,it])=>it.slot===slot&&(UI.armoryLocked||it.tier<=G.tier)).map(([k,it])=>{const locked=it.tier>G.tier;return `<article class="icard ${locked?'locked':''}"><div class="lbl gold">${SLOTS[it.slot]}</div><h3>${esc(it.n)}</h3><p>${esc(modText(it.m))}</p><span class="note">${locked?'Unlocks in '+TIERS[it.tier].n:'Owned '+owned(k)}</span><button class="btn ${locked?'':'pri'} sm" data-act="ibuy" data-k="${k}" aria-label="Buy ${esc(it.n)} for ${it.price} gold" ${locked||G.gold<it.price?'disabled':''}>${locked?'Division locked':G.gold<it.price?'Need '+(it.price-G.gold)+' more gold':'Buy · '+it.price+' gold'}</button></article>`}).join('')}</div><button class="linkbtn armory-more" data-act="armoryLocked">${UI.armoryLocked?'Hide future stock':'Preview higher-division equipment'}</button></section>
 <section class="panel" data-guide="stash"><div class="row between"><h3>Shared stash · ${SLOTS[slot]}</h3><span class="lbl">Ready to equip</span></div>${stash.length?stash.map(x=>`<div class="stash-row"><div><b>${esc(ITEMS[x.key].n)}</b><small>${esc(modText(ITEMS[x.key].m))}</small></div><div class="row"><button class="btn sm" data-act="equip" data-id="${b.id}" data-item="${x.id}">Equip on ${esc(b.name)}</button><button class="linkbtn" data-act="isell" data-item="${x.id}" aria-label="Sell ${esc(ITEMS[x.key].n)} for ${Math.round(ITEMS[x.key].price*.5)} gold">Sell · ${Math.round(ITEMS[x.key].price*.5)}</button></div></div>`).join(''):'<p class="empty">No spare pieces in this slot. A purchase appears here until you equip it.</p>'}<p class="note">Each copy equips to one beast. Unequip it from Gear to pass it to someone else. Selling returns half the purchase price.</p></section></div>
 <section class="panel armory-supplies" data-guide="supplies"><span class="lbl gold">One use per supply</span><h3>Recovery supplies</h3><p class="note">Buy here, then use from a beast’s Gear tab. Fresh beasts do not need recovery supplies.</p>${Object.entries(CONS).filter(([k])=>!G.arenaRules||['tonic','salt','poultice'].includes(k)).map(([k,c])=>`<div class="supply-row"><div><b>${c.n}</b><small>${c.d}</small><span class="note">In supply · ${G.cons[k]||0}</span></div><button class="btn sm" data-act="cbuy" data-k="${k}" aria-label="Buy ${c.n} for ${c.price} gold" ${G.gold<c.price?'disabled':''}>Buy · ${c.price}</button></div>`).join('')}<button class="btn" data-act="profile" data-id="${b.id}" data-pt="gear">Use supplies on ${esc(b.name)}</button></section></div></div>`;
};
ACT.armorySlot=d=>{if(SLOTS[d.k]){UI.armorySlot=d.k;render()}};
ACT.armoryLocked=()=>{UI.armoryLocked=!UI.armoryLocked;render()};
ACT.openArmory=d=>{if(!canManageClub())return;UI.armoryBeast=d.id;UI.modal=null;UI.mode='hub';UI.tab='shop';render();window.scrollTo(0,0)};
document.addEventListener('change',e=>{if(e.target.dataset.chg==='armoryBeast'&&clubBeasts().some(b=>b.id===e.target.value)){UI.armoryBeast=e.target.value;render()}});
ACT.ibuy=d=>{const it=ITEMS[d.k];if(!canManageClub()||!it||it.tier>G.tier||G.gold<it.price)return;const item={id:'i'+G.nid++,key:d.k};G.gold-=it.price;G.stash.push(item);UI.armoryPurchase=item.id;ledger(`Bought ${it.n}`,-it.price);save();render();toast(`${it.n} is in your stash. Equip it on your chosen beast.`)};
const flowEquip=ACT.equip;ACT.equip=d=>{const b=G?.beasts[d.id],item=G?.stash.find(x=>x.id===d.item);if(!canManageClub()||b?.clubId!=='P'||!item)return;flowEquip(d);toast(`${ITEMS[item.key].n} equipped on ${b.name}.`)};
for(const action of ['unequip','use']){const previous=ACT[action];ACT[action]=d=>{if(canManageClub()&&G.beasts[d.id]?.clubId==='P')previous(d)}}
const flowSupplyBuy=ACT.cbuy;ACT.cbuy=d=>{if(!canManageClub()||!CONS[d.k]||G.gold<CONS[d.k].price)return;flowSupplyBuy(d);toast(`${CONS[d.k].n} added. Open a beast’s Gear tab to use it.`)};
const flowGear=gearHtml;gearHtml=function(b,edit){return `<section data-guide="gear"><div class="gear-help"><p>Equipment stays attached between matches. Supplies are consumed when used. A disabled Use button means you have none, or this beast does not need it.</p>${edit?`<button class="btn sm" data-act="openArmory" data-id="${b.id}">Buy equipment & supplies</button>`:''}</div>${flowGear(b,edit&&canManageClub()).replace('Buy gear and supplies in the Item shop.','Buy equipment and supplies in the Armory.')}</section>`};

modalSettings=function(m){return `<h2>Club office</h2><p class="note">Make the arena comfortable. Changes save automatically.</p><section class="settings-section" data-guide="settings"><h3>Sound & motion</h3><div class="row" style="margin-top:14px"><button class="btn sm" data-act="music" aria-pressed="${MUS.on}">${MUS.on?'Music on':'Music off'}</button><label for="vol">Music volume</label><input type="range" id="vol" min="0" max="1" step="0.05" value="${MUS.vol}" aria-label="Music volume"></div><div class="settings-grid"><label><input type="checkbox" data-pref="sfx" ${PREFS.sfx?'checked':''}> Combat and interface sounds</label><label><input type="checkbox" data-pref="motion" ${PREFS.motion?'checked':''}> Cinematic motion</label><label><input type="checkbox" data-pref="effects" ${PREFS.effects?'checked':''}> Spell glow and particles</label></div><p class="note">During a match: Space pauses, 1 / 2 / 4 change speed, and M toggles music when you are not typing in a control. Reduced motion follows your device until you change it here.</p></section><details class="office-details"><summary>Club name & identity</summary><label class="lbl" for="clubname">Club name</label><div class="row"><input type="text" id="clubname" value="${esc(G.name)}" maxlength="32"><button class="btn sm" data-act="rename">Rename</button></div><p class="note">Your crest’s initials update with your club’s name.</p></details><details class="office-details"><summary>Save a backup or load another club</summary><p class="note">Your club saves in this browser automatically. Copy the code to keep a backup or move it to another device. Loading replaces the current club.</p><label class="lbl" for="exp">Your save code</label><textarea id="exp" readonly>${esc(exportSave())}</textarea><div class="row"><button class="btn sm" data-act="copy">Copy save code</button><span id="copymsg" class="note"></span></div><label class="lbl" for="imp">Load a save code</label><textarea id="imp" placeholder="Paste a save code here"></textarea><div class="row"><button class="btn sm" data-act="import">Load this club</button><span id="impmsg" class="note"></span></div></details><details class="office-details" ${m.confirm?'open':''}><summary>Found a new club</summary>${m.confirm?'<div class="confirm"><span>Your current club is replaced only when you open the new club’s gates.</span><button class="btn danger sm" data-act="newok">Start over</button><button class="btn sm" data-act="newno">Cancel</button></div>':'<p class="note">Begin again with a new name and a new founding cast.</p><button class="btn danger sm" data-act="new">Found a new club</button>'}</details>`};
const flowMusic=ACT.music;ACT.music=()=>{flowMusic();if(UI.modal?.k==='settings')renderModal()};
for(const action of ['sel','unsel','autopick']){const previous=ACT[action];ACT[action]=(...args)=>{previous(...args);if(UI.mode==='prematch'&&UI.ctx&&!UI.ctx.draft){G.lineups[UI.ctx.fmt]=UI.sel.slice();save()}}}

function matchReadiness(){
 const selected=UI.sel.map(id=>G.beasts[id]).filter(Boolean),required=UI.ctx?.fmt||5;
 const choices=selected.reduce((n,b)=>n+(b.rolls||0)+techniquePoints(b),0),tired=selected.filter(b=>b.energy<50||b.inj||b.fat>55);
 const held=selected.filter(b=>b.tactics.ability==='disabled'),partners=selected.filter(b=>['guard','assist'].includes(b.tactics.stance)&&(!b.tactics.partner||!UI.sel.includes(b.tactics.partner)));
 return {selected,required,choices,tired,held,partners,full:selected.length===required};
}
function readinessHtml(){const r=matchReadiness();return `<section class="panel match-readiness" data-guide="readiness"><div><span class="lbl gold">Final check</span><h3>Ready for the gates?</h3><p class="note">Beasts fight automatically. Your lineup, gear, and instructions carry into the arena.</p></div><div class="readiness-grid"><div class="${r.full?'ready':'attention'}"><b>${r.selected.length} / ${r.required} beasts selected</b><small>${r.full?'Your lineup is complete.':'Bench a beast, then choose a replacement below.'}</small></div><div class="${r.tired.length?'attention':'ready'}"><b>${r.tired.length?'Check fitness':'Your lineup is fresh'}</b><small>${r.tired.length?r.tired.map(b=>esc(b.name)).join(', ')+' · rest or use supplies.':'No low energy, high fatigue, or injuries.'}</small></div><div class="${r.choices?'attention':'ready'}"><b>${r.choices} free development choices</b><small>${r.choices?'Optional: open Skills to spend them before battle.':'Your available powers and techniques are assigned.'}</small></div><div class="${r.held.length||r.partners.length?'attention':'ready'}"><b>${r.held.length||r.partners.length?'Review instructions':'Instructions checked'}</b><small>${r.held.length?'Abilities held: '+r.held.map(b=>esc(b.name)).join(', ')+'. ':''}${r.partners.length?'Missing partners: '+r.partners.map(b=>esc(b.name)).join(', ')+'.':''}${!r.held.length&&!r.partners.length?'Abilities enabled; required partners are fielded.':''}</small></div></div><p class="note">Equipment and paid upgrades are optional. You can win with your founding team. Start at 1× speed; pause to inspect the fight.</p><div class="match-launch"><button class="btn" data-act="go" data-w="0" ${r.full?'':'disabled'}>Resolve without watching</button><button class="btn pri" data-act="go" data-w="1" ${r.full?'':'disabled'}>Enter the arena <span aria-hidden="true">→</span></button></div></section>`}
const flowPrematch=viewPrematch;viewPrematch=function(){const formation=formationHtml();let html=flowPrematch().replace(formation,'');html=html.replace(/<div class="row"><button class="btn" data-act="go"[\s\S]*?<\/div><\/div>/,`<div class="prep-sequence"><span>01 Scout</span><span>02 Select</span><span>03 Arrange</span><span>04 Launch</span></div></div>`);html=html.replace('Best rested','Suggest rested lineup');html=html.replace('<section class="panel"><div class="row between"><h3>Your lineup','<section class="panel" data-guide="lineup"><div class="row between"><h3>Your lineup');html=html.replace('<section class="panel"><div class="row">','<section class="panel" data-guide="scouting"><div class="row">');return html+formation+readinessHtml()};

// The formation is the single source of truth when changing a starting line.
document.addEventListener('change',e=>{const d=e.target.dataset,b=G?.beasts[d.id];if(b&&d.chg==='tac'&&d.k==='pos'&&b.formation){const col={back:0,flank:1,front:2}[e.target.value];if(UI.mode==='prematch'&&UI.sel.includes(b.id))moveFormation(b.id,col,b.formation.row);else b.formation.col=col;save();render()}});
